  "use strict";

  if (window.__dxbi && typeof window.__dxbi.destroy === "function") {
    try { window.__dxbi.destroy(); } catch (_) { /* previous instance already gone */ }
  }

  const API = typeof StremioEnhancedAPI !== "undefined" ? StremioEnhancedAPI : null;
  // Stremio Enhanced loads each plugin as <script id="<file name>">, which tells us our settings key
  const SCRIPT_ID = (document.currentScript && document.currentScript.id) || "dxbi.plugin.js";
  const PLUGIN_KEY = SCRIPT_ID.replace(/\.plugin\.js$/, "");
  const PLUGIN_VERSION = "2.15.9"; // kept in step with @version by tools/bundle-theme.mjs
  const log = (...args) => console.log("[dx.bi]", ...args);
  // dx.bi also comes as its own desktop app (built on Stremio Enhanced): messages name the app
  // you're in, and the folder its streaming server lives in
  const IN_APP = /\bdxbi\//.test(navigator.userAgent);
  // dx.bi TV (Android TV) plays every stream in its own native player, so the in-page player
  // features (seek previews, picture panel, skip buttons, watch parties…) stand aside there
  const IN_TV = /\bdxbi-tv\//.test(navigator.userAgent);
  // A TV's processor can't keep up with smooth scrolling: the selection then sits off screen for a
  // moment after each press. Jumps keep it in sight.
  const SCROLL = IN_TV ? "instant" : "smooth";
  const SETTINGS_SECTION = IN_APP || IN_TV ? "dx.bi" : "Enhanced";
  const APP_NAME = IN_APP ? "dx.bi" : "Stremio Enhanced";


  // Stremio Web can drop window.core on some routes (Stremio Enhanced works around the same thing),
  // so keep the first working getState/dispatch we see and fall back to Enhanced's own copy.
  const keptCore = { getState: null, dispatch: null };
  function core() {
    const live = window.core || (window.services && window.services.core);
    if (live) {
      if (!keptCore.getState && typeof live.getState === "function") keptCore.getState = live.getState.bind(live);
      if (!keptCore.dispatch && typeof live.dispatch === "function") keptCore.dispatch = live.dispatch.bind(live);
    }
    const perm = window.__permanentCore || {};
    return {
      getState: keptCore.getState || perm.getState || null,
      dispatch: keptCore.dispatch || perm.dispatch || null,
    };
  }

